#!/usr/bin/env python3
"""
Round nh2 (culprits), 16 October 2026, from the Invasion of non-humans chat.
Needs round nh1.

Adds, where the owner asked: bottom trawling and dredging inside marine
protected areas, straight under Biodiversity loss; and the six Worldwide
Governance Indicators under Biodiversity loss > How the countries are
governed. Updates the Invasion of non-humans row's note for the map's new
parts. Changes map/app.js and map/test.mjs only.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round nh2 (16 October, the Invasion of non-humans chat)\n\nNeeds round nh1 (guards on its heading).\n\n- New rows, filed where the owner asked:\n  - **trawl_mpas** (route geojsonlive; NOT_LIVE entry) straight under Destruction > Of the planet >\n    Biodiversity loss: every marine and partly marine area of the WDPA as a dot, with Global\n    Fishing Watch trawler and dredge hours inside it (tiles nonhuman_trawl_mpas.py, reusing\n    gfw_trawling.ask and the GFW_TOKEN secret; squares weighted by the share the boundary covers).\n  - **wgi_va, wgi_pv, wgi_ge, wgi_rq, wgi_rl, wgi_cc** (route country, totalsFrom\n    nonhuman/wgi.json, field <key>_rank, linear 0-100, reverse) under a new heading\n    Biodiversity loss > How the countries are governed (the page's footnote 19.7; tiles\n    nonhuman_wgi.py, World Bank source 3).\n  - Two older checks in map/test.mjs (round 23 / 99b) now allow a row straight under\n    Biodiversity loss and the new last heading.\n- The owner's free-flowing rivers request (Grill et al. 2019) was already on the map as fish_rivers\n  under Biodiversity loss > Fish; nothing added.\n- nonhuman_atlas's note lists the map's new parts: where pesticides are made (EPA, live; E-PRTR),\n  EU banned pesticide exports (Unearthed and Public Eye), PAN's banned pesticides, roads (GRIP4),\n  drained wetlands (Fluet-Chouinard et al. 2023), human modification inside each protected area,\n  and oil and gas sites (OGIM) by distance from protected areas. Those live in the map's own\n  code (maps repo invasion-of-nonhumans.html), not here.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("nonhuman2: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round nh1" not in h.read_text(encoding="utf-8"):
        sys.exit("nonhuman2: round nh1 must be applied first (nonhuman1_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("nonhuman2: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("nonhuman2: the diff did not apply:\n" + r.stdout + r.stderr)
        print("nonhuman2: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
